}
+ (NSString *)photoDirectory {
    NSString *root =
        NSSearchPathForDirectoriesInDomains(NSApplicationSupportDirectory, NSUserDomainMask, YES).firstObject;
    NSString *path = [root stringByAppendingPathComponent:@"TuyuPhotos"];
    [NSFileManager.defaultManager
              createDirectoryAtPath:path
        withIntermediateDirectories:YES
                         attributes:@{
                             NSFileProtectionKey : NSFileProtectionCompleteUntilFirstUserAuthentication
                         }
                              error:nil];
    return path;
}
+ (UIImage *)imageForKey:(NSString *)key {
    if ([key hasPrefix:@"user-"]) {
        UIImage *image =
            [UIImage imageWithContentsOfFile:[[self photoDirectory]
                                                 stringByAppendingPathComponent:key.lastPathComponent]];
        if (image)
            return image;
    }
    return [key isEqual:@"mountain"] ? [self mountainImage] : [self forestImage];
}
+ (NSString *)saveImage:(UIImage *)image error:(NSError **)error {
    CGFloat ratio = MIN(1, 1000 / MAX(image.size.width, image.size.height));
    CGSize size = CGSizeMake(MAX(1, image.size.width * ratio), MAX(1, image.size.height * ratio));
    UIGraphicsImageRendererFormat *format = [UIGraphicsImageRendererFormat defaultFormat];
    format.scale = 1;
    UIGraphicsImageRenderer *renderer = [[UIGraphicsImageRenderer alloc] initWithSize:size format:format];
    UIImage *small = [renderer imageWithActions:^(UIGraphicsImageRendererContext *context) {
        [image drawInRect:(CGRect){CGPointZero, size}];
    }];
    NSData *data = UIImageJPEGRepresentation(small, .8);
    NSString *name = [NSString stringWithFormat:@"user-%@.jpg", NSUUID.UUID.UUIDString];
    if ([data writeToFile:[[self photoDirectory] stringByAppendingPathComponent:name]
                  options:NSDataWritingAtomic
                    error:error])
        return name;
    return nil;
}
+ (void)removeUserImages {
    [NSFileManager.defaultManager removeItemAtPath:[self photoDirectory] error:nil];
}
@end
